// Modifier is the resolver for the modifier field.
func (r *abilityScoreResolver) Modifier(ctx context.Context, obj *model.AbilityScore) (int32, error) {
	if obj.Score < 4 {
		return -3, nil
	}

	if obj.Score < 6 {
		return -2, nil
	}

	if obj.Score < 9 {
		return -1, nil
	}

	if obj.Score < 13 {
		return 0, nil
	}

	if obj.Score < 16 {
		return 1, nil
	}

	if obj.Score < 18 {
		return 2, nil
	}

	return 3, nil
}

