// Create is the resolver for the create field.
func (r *characterMutationResolver) Create(ctx context.Context, obj *model.CharacterMutation, input model.CreateCharacterInput) (*model.Character, error) {
	// Parse ability scores from the input slice into individual vars.
	var charisma, constitution, dexterity, intelligence, strength, wisdom int32
	for _, ab := range input.Abilities {
		switch ab.Ability {
		case model.AbilityCharisma:
			charisma = ab.Score
		case model.AbilityConstitution:
			constitution = ab.Score
		case model.AbilityDexterity:
			dexterity = ab.Score
		case model.AbilityIntelligence:
			intelligence = ab.Score
		case model.AbilityStrength:
			strength = ab.Score
		case model.AbilityWisdom:
			wisdom = ab.Score
		}
	}

	characterClassModel, ok := (*r.CharacterClasses)[input.CharacterClassKey]
	if !ok {
		return nil, fmt.Errorf("No class with key '%s'", input.CharacterClassKey)
	}

	// Get initial hit points
	hitPoints := constitution + characterClassModel.HpBase

	// Resolve starting gear ahead of any inserts: the class's defaults, plus
	// whatever the player picked from its pick-N option groups, split into
	// items to persist and gold to add to the character row directly. Some
	// items (e.g. the Fighter's Signature Weapon) resolve from the move
	// creation option choices rather than a template — see
	// StartingGearModel.ResolveItems.

	moveChoiceMap := models.BuildMoveChoiceMap(input.MoveCreationOptionChoices, func(c *model.MoveCreationOptionChoiceInput) (string, int32, string) {
		return c.MoveKey, c.ChoiceIndex, c.OptionKey
	})

	startingGear := characterClassModel.StartingGear.ResolveItems(models.StartingGearContext{
		CharacterClass: &characterClassModel,
		MoveChoices:    moveChoiceMap,
	}, input.GearOptionChoices)

	// Run all inserts in a single transaction.
	tx, err := r.DbPool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("Failed to begin transaction: %w", err)
	}
	defer tx.Rollback(ctx)

	queries := db.New(tx)

	// Insert the character row.
	characterId, err := queries.InsertCharacter(ctx, db.InsertCharacterParams{
		AlignmentDescription: input.AlignmentDescription,
		AlignmentType:        input.AlignmentType,
		CharacterClassKey:    input.CharacterClassKey,
		Charisma:             charisma,
		Constitution:         constitution,
		Dexterity:            dexterity,
		Gold:                 startingGear.Gold,
		HitPoints:            hitPoints,
		Intelligence:         intelligence,
		Name:                 input.Name,
		RaceMoveKey:          input.RaceMoveKey,
		Strength:             strength,
		Wisdom:               wisdom,
	})
	if err != nil {
		return nil, fmt.Errorf("Failed to insert character: %w", err)
	}

	// Insert looks.

	for _, look := range input.Looks {
		if _, err = queries.InsertLook(ctx, db.InsertLookParams{
			CharacterID: characterId,
			LookType:    look.LookTypeKey,
			Value:       look.Value,
		}); err != nil {
			return nil, fmt.Errorf("Failed to insert look: %w", err)
		}
	}

	// Insert move creation option choices.
	for _, choice := range input.MoveCreationOptionChoices {
		if _, err = queries.InsertMoveCreationOptionChoice(ctx, db.InsertMoveCreationOptionChoiceParams{
			CharacterID: characterId,
			ChoiceIndex: choice.ChoiceIndex,
			MoveKey:     choice.MoveKey,
			OptionKey:   choice.OptionKey,
		}); err != nil {
			return nil, fmt.Errorf("Failed to insert move creation option choice: %w", err)
		}
	}

	// Insert starting gear items (gold was already folded into the character
	// row above).

	for _, item := range startingGear.Items {
		var label, description pgtype.Text
		if item.Label != nil {
			label = pgtype.Text{String: *item.Label, Valid: true}
		}
		if item.Description != nil {
			description = pgtype.Text{String: *item.Description, Valid: true}
		}

		itemId, err := queries.InsertItem(ctx, db.InsertItemParams{
			CharacterID: characterId,
			Count:       item.Count,
			Description: description,
			Key:         item.Key,
			Label:       label,
		})
		if err != nil {
			return nil, fmt.Errorf("Failed to insert item: %w", err)
		}

		for _, tag := range item.Tags {
			var quantity pgtype.Int4
			if tag.Quantity != nil {
				quantity = pgtype.Int4{Int32: *tag.Quantity, Valid: true}
			}

			if _, err = queries.InsertItemTag(ctx, db.InsertItemTagParams{
				ItemID:   itemId,
				Key:      tag.Key,
				Quantity: quantity,
			}); err != nil {
				return nil, fmt.Errorf("Failed to insert item tag: %w", err)
			}
		}
	}

	if err = tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("Failed to commit transaction: %w", err)
	}

	characterModel, err := r.Loaders.CharacterLoader.Load(ctx, characterId)
	if err != nil {
		return nil, fmt.Errorf("Failed to load character with ID '%s' after creation: %w", characterId, err)
	}

	return models.ToCharacterObject(characterModel), nil
}

